{
  "name": "@mageyuki/opencode-subagent-statusline",
  "version": "0.7.1",
  "description": "Unofficial fork of opencode-subagent-statusline: OpenCode plugin that exposes subagent session statusline state, with a V2 bridge",
  "type": "module",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/mageyuki/sub-agent-statusline.git"
  },
  "bugs": {
    "url": "https://github.com/mageyuki/sub-agent-statusline/issues"
  },
  "homepage": "https://github.com/mageyuki/sub-agent-statusline#readme",
  "engines": {
    "node": ">=22.13"
  },
  "main": "./dist/tui.js",
  "types": "./dist/tui.d.ts",
  "exports": {
    ".": {
      "types": "./dist/tui.d.ts",
      "import": "./dist/tui.js"
    },
    "./tui": {
      "types": "./dist/tui.d.ts",
      "import": "./dist/tui.js"
    },
    "./runtime": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist",
    "assets",
    "README.md"
  ],
  "publishConfig": {
    "access": "public",
    "provenance": true
  },
  "keywords": [
    "opencode",
    "plugin",
    "statusline",
    "subagent"
  ],
  "license": "MIT",
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.14.50 <2",
    "@opencode/plugin": "2.0.11",
    "@opencode/theme": "2.0.11",
    "@opentui/core": ">=0.4.0 <0.6",
    "@opentui/keymap": ">=0.4.0 <0.6",
    "@opentui/solid": ">=0.4.0 <0.6",
    "solid-js": ">=1.9.12 <2"
  },
  "peerDependenciesMeta": {
    "@opencode-ai/plugin": {
      "optional": true
    },
    "@opencode/plugin": {
      "optional": true
    },
    "@opencode/theme": {
      "optional": true
    },
    "@opentui/core": {
      "optional": true
    },
    "@opentui/keymap": {
      "optional": true
    },
    "@opentui/solid": {
      "optional": true
    },
    "solid-js": {
      "optional": true
    }
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.15.11",
    "@opencode/client": "2.0.11",
    "@opencode/plugin": "2.0.11",
    "@opencode/theme": "2.0.11",
    "@opentui/core": "0.5.10",
    "@opentui/keymap": "0.5.10",
    "@opentui/solid": "0.5.10",
    "@types/node": "^22.19.19",
    "@vitest/coverage-v8": "^4.1.7",
    "esbuild-plugin-solid": "^0.6.0",
    "solid-js": "1.9.12",
    "tsup": "^8.5.1",
    "typescript": "^5.9.3",
    "vitest": "^4.1.7"
  },
  "scripts": {
    "build": "node --input-type=module -e \"import { rm } from 'node:fs/promises'; await rm('dist', { recursive: true, force: true });\" && tsup",
    "audit:prod": "pnpm audit --prod --audit-level moderate",
    "pack:dry-run": "pnpm pack --dry-run",
    "test": "vitest run",
    "test:package": "pnpm build && vitest run --config vitest.package.config.ts",
    "test:watch": "vitest",
    "test:coverage": "vitest run --coverage",
    "typecheck": "tsc --noEmit -p tsconfig.json",
    "dev": "tsup --watch"
  }
}
